import java.util.Scanner;
class Main {
int calculateEvenSum(int n) {
int total = 0;
// Add the first n even numbers
for (int i = 1; i <= n; i++) {
total = total + (i * 2);
}
return total;
}
public static void main(String[] args) {
Scanner input = new Scanner(System.in);
int number = input.nextInt();
Main obj = new Main();
int total = obj.calculateEvenSum(number);
System.out.println(total);
input.close();
}
}

class Main {
int getHighestScore(int score1, int score2, int score3) {
// Find the highest score
if (score1 >= score2 && score1 >= score3) {
return score1;
}
else if (score2 >= score1 && score2 >= score3) {
return score2;
}
else {
return score3;
}
}
public static void main(String[] args) {
Main game = new Main();
int highest = game.getHighestScore(72, 91, 68);
System.out.println(highest); // Output: 91
highest = game.getHighestScore(84, 77, 95);
System.out.println(highest); // Output: 95
}
}

class Main {
int getHighestRating(int rating1, int rating2, int rating3) {
int highest;
if (rating1 >= rating2 && rating1 >= rating3) {
highest = rating1;
}
else if (rating2 >= rating1 && rating2 >= rating3) {
highest = rating2;
}
else {
highest = rating3;
}
return highest;
}
public static void main(String[] args) {
Main obj = new Main();
